/**
 * Archives many issues of one organization. Unknown ids, ids from another
 * organization, and issues that are already archived are skipped. Every issue
 * that will be archived is permission-checked first; one denial rejects the
 * whole call before any row or event is written.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const uniqueIds: IssueId[] = [];
  const seen = new Set<string>();
  for (const issueId of input.issueIds) {
    if (seen.has(issueId)) continue;
    seen.add(issueId);
    uniqueIds.push(issueId);
  }

  const found = await issueRepo.findIssuesByIds(input.orgId, uniqueIds);
  const byId = new Map(found.map((issue) => [issue.id, issue]));

  const toArchive: Issue[] = [];
  const skipped: IssueId[] = [];
  for (const issueId of uniqueIds) {
    const issue = byId.get(issueId);
    if (!issue || isArchived(issue)) {
      skipped.push(issueId);
      continue;
    }
    toArchive.push(issue);
  }

  for (const issue of toArchive) {
    assertCan(actor, "issue:archive", issueResource(issue));
  }

  const archived: IssueId[] = [];
  for (const issue of toArchive) {
    const result = await issueRepo.archiveIssue(input.orgId, issue.id);
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: result.id,
      projectId: result.projectId,
    });
    archived.push(result.id);
  }

  return { archived, skipped };
}

